import{_ as a,a0 as l,w as d,s as r,I as p,x as e,a1 as n,A as i,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"已经会用Git了？不会这十招怎么行 | LCTT x X-CMD","titleTemplate":false,"description":"已经会用Git了？不会这十招怎么行 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"已经会用Git了？不会这十招怎么行 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"已经会用Git了？不会这十招怎么行 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140620 Tips to Push Your Git Skills to the Next Level","title":"已经会用Git了？不会这十招怎么行","tag":"201407","desc":""},"relativePath":"201407/20140620 Tips to Push Your Git Skills to the Next Level.md","filePath":"[post].md"}'),c={name:"201407/20140620 Tips to Push Your Git Skills to the Next Level.md"};function g(h,t,m,u,f,b){const o=l("Link");return d(),r("div",null,[t[16]||(t[16]=p("h1",{id:"已经会用git了-不会这十招怎么行",tabindex:"-1"},[e("已经会用Git了？不会这十招怎么行 "),p("a",{class:"header-anchor",href:"#已经会用git了-不会这十招怎么行","aria-label":"Permalink to “已经会用Git了？不会这十招怎么行”"},"​")],-1)),p("p",null,[t[2]||(t[2]=e("之前我们发了一些教程让你熟悉",-1)),n(o,{href:"http://www.sitepoint.com/git-for-beginners/"},{default:i(()=>[...t[0]||(t[0]=[e("Git基础",-1)])]),_:1}),t[3]||(t[3]=e("和",-1)),n(o,{href:"http://www.sitepoint.com/getting-started-git-team-environment/"},{default:i(()=>[...t[1]||(t[1]=[e("在团队合作环境中使用Git",-1)])]),_:1}),t[4]||(t[4]=e(".我们讨论的这些Git命令足够让一个开发者在Git的世界里生存下去。在这篇教程里，我们试着探索如何高效地管理你的时间以及如何充分利用Git提供的特性。",-1))]),t[17]||(t[17]=s(`<blockquote><p>注意：这里介绍的命令中有的包含方括号(例如：<code>git add -p [file_name]</code>)。在这些例子中，你应该用你自己的数字、标识符等替代方括号里的内容，并且去掉方括号。</p></blockquote><h3 id="_1-git自动补全" tabindex="-1">1. Git自动补全 <a class="header-anchor" href="#_1-git自动补全" aria-label="Permalink to “1. Git自动补全”">​</a></h3><p>如果你在命令行环境中运行Git命令，每次都手动地逐个输入命令是一件很无聊的事。为此，你可以花几分钟时间配置一下Git命令的自动补全功能。</p><p>在*nix系统运行下列命令下载自动补全脚本：</p><pre><code>cd ~
curl https://raw.github.com/git/git/master/contrib/completion/git-completion.bash -o ~/.git-completion.bash
</code></pre><p>然后，添加下面的行到你的~/.bash_profile文件：</p><pre><code>if [ -f ~/.git-completion.bash ]; then
    . ~/.git-completion.bash
fi
</code></pre><p>尽管我之前已经提到过，但我还是想再强调一下：如果你想使用完整的Git特性，你绝bi应该切换到命令行环境。</p><h3 id="_2-在git中忽略文件" tabindex="-1">2. 在Git中忽略文件 <a class="header-anchor" href="#_2-在git中忽略文件" aria-label="Permalink to “2. 在Git中忽略文件”">​</a></h3><p>你是不是对出现在你Git库里面的编译生成文件（比如<code>.pyc</code>)感到很无语？或者你是不是很厌恶不小心将他们添加到了Git？直接看这里，这里有一个方法可以让你告诉Git忽略所有这些文件和目录。只需要创建一个名字为<code>.gitignore</code>的文件，里面列出你不想要Git跟踪的文件和目录。可以用感叹号(!)列出例外情况。</p><pre><code>*.pyc
*.exe
my_db_config/
 
!main.pyc
</code></pre><h3 id="_3-谁动了我的代码" tabindex="-1">3. 谁动了我的代码？ <a class="header-anchor" href="#_3-谁动了我的代码" aria-label="Permalink to “3. 谁动了我的代码？”">​</a></h3><p>当事情出了乱子时立马责怪别人这是人类的天性。如果你的服务器程序不能正常工作了，要找出罪魁祸首是非常简单的--只需要执行<code>git blame</code>。这个命令告诉你文件里的每一行的作者是谁，最后改动那一行的提交，以及提交的时间戳。</p><pre><code>git blame [file_name]
</code></pre><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946443git-ninja-01.png" alt="git blame demonstration"></p><p>在下面的截图里，你可以看到在一个更大的库里这个命令的输出是什么样的：</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946441git-ninja-02.png" alt="git blame on the ATutor repository"></p><h3 id="_4-查看库的历史" tabindex="-1">4. 查看库的历史 <a class="header-anchor" href="#_4-查看库的历史" aria-label="Permalink to “4. 查看库的历史”">​</a></h3><p>在之前的教程里，我们已经看过了如何使用<code>git log</code>命令。不管怎样，有3个选项你应该知道。</p><ul><li><strong>--oneline</strong> - 压缩每次的提交信息，只保留一个缩减的Hash值和说明文字，然后把这些都展示在一行里。</li><li><strong>--graph</strong> - 这个选项将在左边画出一个文字界面的提交历史图。如果你只有一个分支，用这个选项查看历史时是没什么意义的。</li><li><strong>--all</strong> - 显示所有分支历史。</li></ul><p>这是这3个选项合起来使用的效果：</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946444git-ninja-03.png" alt="Use of git log with all, graph and oneline"></p><h3 id="_5-不要丢失对某个提交的跟踪" tabindex="-1">5. 不要丢失对某个提交的跟踪 <a class="header-anchor" href="#_5-不要丢失对某个提交的跟踪" aria-label="Permalink to “5. 不要丢失对某个提交的跟踪”">​</a></h3><p>假设你提交了一些不需要的东西，然后你进行了hard重置回到之前的状态。后来，你发现在这个过程中你丢失了其他一些重要的信息，你想要把这些信息找回来，或者至少可以查看一下这些信息。这就需要<code>git reflog</code>帮忙。</p><p>简单的<code>git log</code>只能告诉你最近的提交，这个提交的父提交，父提交的父提交，等等。但是<code>git reflog</code>是一个HEAD指向的提交的列表。记住，这个列表依赖于你自己的本地操作环境，它不是库的一部分，也不包含在push或者merge中。</p><p>如果执行<code>git log</code>命令，可以看到提交历史，这是我的库的一部分：</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946446git-ninja-04.png" alt="Project history"></p><p>但是，<code>git reflog</code>命令显示了一个被我用hard重置丢掉的提交(<code>b1b0ee9</code>-<code>HEAD@{4}</code>).</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946447git-ninja-05.png" alt="Git reflog"></p><h3 id="_6-暂存文件的一部分更改以便进行一次提交" tabindex="-1">6. 暂存文件的一部分更改以便进行一次提交 <a class="header-anchor" href="#_6-暂存文件的一部分更改以便进行一次提交" aria-label="Permalink to “6. 暂存文件的一部分更改以便进行一次提交”">​</a></h3><p>通常依据特性来提交是一个好的实践方法，意思是说，每一个提交都只添加一个特性或者修复一个bug。想一下如果你一次修复了两个bug或者添加了两个特性但是都还没有逐个提交该怎么办。这种场景下，你可以将他们一起提交。但是有一个更好的办法：单独暂存这些文件，然后分开提交。</p><p>让我们假设你对一个文件做了多个更改，然后想让这些更改分开提交。这时，我们用带<code>-p</code>的添加命令。</p><pre><code>git add -p [file_name]
</code></pre><p>我们来试试这种用法。我添加了3个新行到<code>file_name</code>，但是我只想让第1行和第3行出现在我的提交里。让我们看看<code>git diff</code>的输出是什么样的。</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946449git-ninja-06.png" alt="Changes in repo"></p><p>然后，我们看看带<code>-p</code>选项的<code>add</code>命令会发生什么。</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946450git-ninja-07.png" alt="Running add with -p"></p><p>看起来Git认为所有的更改都是同一个目的的一部分，所以把他们分组到同一个块里。这时，你可以：</p><ul><li>输入 y 暂存块</li><li>输入 n 不暂存块</li><li>输入 e 手动编辑块</li><li>输入 d 退出或者跳转到下一个文件</li><li>输入 s 分割块</li></ul><p>在我们这个例子中，我们想把这个块分割成更小的部分，然后选择其中一些忽略另外一些。</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946452git-ninja-08.png" alt="Adding all hunks"></p><p>如你所见，我们已经逐个添加了第1和第3行，忽略了第2行。你可以看到库的状态并且进行一次提交。</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946454git-ninja-09.png" alt="Repository after selectively adding a file"></p><h3 id="_7-合并多个提交" tabindex="-1">7. 合并多个提交 <a class="header-anchor" href="#_7-合并多个提交" aria-label="Permalink to “7. 合并多个提交”">​</a></h3><p>为了进行核查或者发起一个合并请求（这经常发生在开源项目里），对代码进行了修改提交。但在最后代码被接受之前，你也许会需要修改你的代码。于是你修改代码，但是下一次核查的时候又一次需要进行修改。不知不觉中，你就已经有了好几个提交。理论上你应该用rebase命令把他们合并起来。</p><pre><code>git rebase -i HEAD~[number_of_commits]
</code></pre><p>如果你想合并最后的两次提交，你应该运行下面的命令。</p><pre><code>git rebase -i HEAD~2
</code></pre><p>一旦你运行这个命令，你将进入一个交互式界面，它将询问你想要合并哪些提交。你<code>pick</code>(拣选)最近的提交然后<code>squash</code>(合并)旧的提交。</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946455git-ninja-10.png" alt="Git squash interactive"></p><p>接着你应该提供一个对新提交的说明。这个过程会重写你的提交历史。</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946457git-ninja-11.png" alt="Adding a commit message"></p><h3 id="_8-储藏没有提交的更改" tabindex="-1">8. 储藏没有提交的更改 <a class="header-anchor" href="#_8-储藏没有提交的更改" aria-label="Permalink to “8. 储藏没有提交的更改”">​</a></h3><p>假设你正在修复一个bug或者添加一个特性，突然你被要求展示一下你的工作成果。你现在的工作还没有完成，不够进行一次提交。这时，<code>git stash</code>命令可以用来急救一下。Stash命令跟踪你所有的更改，然后把他们储藏起来以便以后使用。命令如下-</p><pre><code>git stash
</code></pre><p>可以多次储藏更改，查看储藏列表，你可以运行下面的命令：</p><pre><code>git stash list
</code></pre><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946458git-ninja-12.png" alt="Stash list"></p><p>如果你想取消储藏，覆盖当前的更改，你可以通过下面的命令使用储藏：</p><pre><code>git stash apply
</code></pre><p>在最后的这个截图里，你可以看到每个储藏都有一个标识符，是一个唯一的数字（尽管在这里我们只有一个储藏）。如果你想使用某个储藏，你在apply命令后面加上这个唯一的标识符：</p><pre><code>git stash apply stash@{2}
</code></pre><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946461git-ninja-13.png" alt="After un-stashing changes"></p><h3 id="_9-检查丢失的提交" tabindex="-1">9. 检查丢失的提交 <a class="header-anchor" href="#_9-检查丢失的提交" aria-label="Permalink to “9. 检查丢失的提交”">​</a></h3><p>尽管<code>reflog</code>是一种检查丢失提交的方法，大型的库里却不太实用。这个时候，应该用<code>fsck</code>（文件系统检查）命令。</p><pre><code>git fsck --lost-found
</code></pre><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946463git-ninja-14.png" alt="Git fsck results"></p><p>这里你可以看到一个丢失的提交。你可以通过<code>git show [commit_hash]</code> 查看提交的更改或者通过运行<code>git merge [commit_hash]</code>命令进行恢复。</p><p><code>git fsck</code>跟<code>reflog</code>命令相比有一个优点。假设你删除了一个远程分支，然后clone了这个库。用<code>fsck</code>命令你可以找到并且恢复这个删除的远程分支。</p><h3 id="_10-最佳选择" tabindex="-1">10. 最佳选择 <a class="header-anchor" href="#_10-最佳选择" aria-label="Permalink to “10. 最佳选择”">​</a></h3><p>之前我已经存记下了那些最优雅的Git命令。但是目前为止，<code>cherry-pick</code>命令是我最喜欢的Git命令，因为它直白的名字和实用的功能！</p><p>最简单的情况下，<code>cherry-pick</code>从另一个分支里选出单独的一个提交，然后合并到当前分支。如果你正并行工作在两个或者更多的分支上，你也许会发现一个存在于所有分支上的bug。如果你解决了一个分支上的这个bug，你可以拣选这个对应的提交应用到其他分支上，而不会弄乱其他文件或者提交。</p><p>让我们来考虑一个可以使用这个命令的场景。我有两个分支，我想拣选<code>b20fd14: Cleaned junk</code>这个提交到另一个分支上。</p><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946465git-ninja-15.png" alt="Before cherry pick"></p><p>我切换到想要应用这个拣选出来的提交的分支，然后运行下面的命令：</p><pre><code>git cherry-pick [commit_hash]
</code></pre><p><img src="http://dab1nmslvvntp.cloudfront.net/wp-content/uploads/2014/06/1402946467git-ninja-16.png" alt="After cherry pick"></p><p>尽管这次我们很干净的用了<code>cherry-pick</code>命令，但你应该知道这个命令经常会引起冲突，所以请小心使用。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>到了这里，我们结束了这个能使你Git能力提升一个级别的列表。Git是最好的版本控制器，它能完成你能想象到的任何事情。所以，经常试着用Git挑战你自己。一不小心你就会学到很多新东西。</p><hr>`,81)),p("p",null,[t[6]||(t[6]=e("via: ",-1)),n(o,{href:"http://www.sitepoint.com/10-tips-git-next-level/"},{default:i(()=>[...t[5]||(t[5]=[e("http://www.sitepoint.com/10-tips-git-next-level/",-1)])]),_:1})]),p("p",null,[t[9]||(t[9]=e("译者：",-1)),n(o,{href:"https://github.com/CNprober"},{default:i(()=>[...t[7]||(t[7]=[e("love_daisy_love",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原创翻译，",-1)),n(o,{href:"http://linux.cn/"},{default:i(()=>[...t[12]||(t[12]=[e("Linux中国",-1)])]),_:1}),t[15]||(t[15]=e(" 荣誉推出",-1))])])}const w=a(c,[["render",g]]);export{k as __pageData,w as default};
